var a=`1001-tom-yum-goong`;var s=`world-1001`;var t=`TH`;var n=`southeast-asia`;var o=4;var m=25;var r={en:`Tom Yum Goong`,ua:`Том ям кунг`};var l={en:`Tom Yum Goong is a dish from Thailand prepared with lemongrass, galangal, makrut lime leaves, shallot. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Том ям кунг, страва кухні країни Таїланд, яку готують із таких продуктів: лемонграс, галангал, листя макрут-лайма, цибуля шалот. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var u=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 15 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 15 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:15,i:[[`water`,900,`ml`],[`lemongrass`,3,`pcs`],[`galangal`,35,`g`],[`makrut-lime-leaves`,5,`leaf`],[`shallot`,75,`g`]]},{en:`Add the cleaned shrimp, mushrooms and tomatoes directly TO the hot aromatic soup, then simmer until shrimp turn opaque (about 4–5 minutes). Do not drain the broth.`,ua:`Додайте очищені креветки, гриби та помідори просто У гарячий ароматний суп і варіть приблизно 4–5 хвилин до непрозорості креветок. Бульйон не зливайте.`,t:[`boiling`],m:5,i:[[`shrimp`,500,`g`],[`straw-mushroom`,250,`g`],[`tomato`,160,`g`]]},{en:`Turn off heat and season with fish sauce, lime juice, chili and curry paste to balance sour, salty and spicy notes; remove tough lemongrass stalks before serving.`,ua:`Вимкніть вогонь і додайте рибний соус, лайм, чилі та пасту карі для балансу кислого, солоного й гострого; перед подаванням вийміть тверді стебла лемонграсу.`,t:[`mixing`],m:3,i:[[`fish-sauce`,40,`ml`],[`lime-juice`,70,`ml`],[`bird-s-eye-chili`,3,`pcs`],[`thai-red-curry-paste`,16,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`cilantro`,20,`g`]]}];var h={slug:a,id:s,country:`TH`,region:n,servings:4,minutes:25,title:r,text:l,steps:u};export{t as country,h as default,s as id,m as minutes,n as region,o as servings,a as slug,u as steps,l as text,r as title};